#pragma once
#include "app_paths.hpp"
#include <set>
#include <cwctype>
#include <sstream>
namespace vamp {
inline std::wstring pluginPathKey(const fs::path& path){auto key=path.lexically_normal().wstring();std::replace(key.begin(),key.end(),L'/',L'\\');while(key.size()>3&&key.back()==L'\\')key.pop_back();std::transform(key.begin(),key.end(),key.begin(),::towlower);return key;}
struct DiscoveredPluginFolder{fs::path path;std::wstring source;};
inline std::wstring trimPluginPath(std::wstring s){auto a=s.find_first_not_of(L" \t\r\n\"'");if(a==s.npos)return{};s=s.substr(a,s.find_last_not_of(L" \t\r\n\"'")-a+1);for(auto pair:{std::pair<const wchar_t*,const wchar_t*>{L"&amp;",L"&"},{L"&quot;",L"\""},{L"&apos;",L"'"},{L"&lt;",L"<"},{L"&gt;",L">"}}){size_t at=0;while((at=s.find(pair.first,at))!=s.npos){s.replace(at,wcslen(pair.first),pair.second);at+=wcslen(pair.second);}}return s;}
// Read only explicit plugin-path entries. Never treat arbitrary paths in a host's
// project history or sample libraries as plugin search locations.
inline std::vector<std::wstring>pluginPathsFromConfig(const std::wstring& text){std::vector<std::wstring>out;std::wstring lower=text;std::transform(lower.begin(),lower.end(),lower.begin(),::towlower);const wchar_t*keys[]={L"vstpath64",L"vstpath",L"vst3path",L"vstpluginsfolder",L"vst2customfolder",L"vst3customfolder",L"vstcustomfolder",L"vstpluginfolder",L"vst2pluginfolder",L"vst3pluginfolder",L"pluginsearchpath",L"vst2xpluginsearchpath",L"vst2xpluginpath",L"vstplugins",L"vst2path",L"vst3folder",L"vst2folder"};
    for(auto key:keys){size_t at=0;while((at=lower.find(key,at))!=lower.npos){size_t end=std::min(text.size(),at+4096);auto stop=text.find_first_of(L"\r\n",at);if(stop!=text.npos)end=std::min(end,stop);std::wstring fragment=text.substr(at,end-at);size_t begin=fragment.find_first_of(L"=:");if(begin!=fragment.npos)fragment=fragment.substr(begin+1);else{begin=fragment.find(L'>');if(begin!=fragment.npos)fragment=fragment.substr(begin+1);}auto pathStart=fragment.find_first_of(L"\\/");if(pathStart!=fragment.npos&&pathStart&&fragment[pathStart-1]==L':')pathStart-=2;else if(pathStart!=fragment.npos&&pathStart>0)pathStart=fragment.npos;if(pathStart!=fragment.npos){fragment=fragment.substr(pathStart);auto cut=fragment.find_first_of(L"\"<>\0");if(cut!=fragment.npos)fragment.resize(cut);fragment=trimPluginPath(fragment);std::wistringstream list(fragment);std::wstring value;while(std::getline(list,value,L';')){value=trimPluginPath(value);if(!value.empty())out.push_back(value);}}at+=wcslen(key);}}
    return out;
}
inline std::wstring readPluginConfig(const fs::path&path){std::error_code ec;auto size=fs::file_size(path,ec);if(ec||size>8*1024*1024)return{};std::ifstream file(path,std::ios::binary);std::string bytes((std::istreambuf_iterator<char>(file)),{});if(bytes.size()>=2&&(uint8_t)bytes[0]==255&&(uint8_t)bytes[1]==254){std::wstring text;for(size_t i=2;i+1<bytes.size();i+=2)text.push_back((uint8_t)bytes[i]|((uint8_t)bytes[i+1]<<8));return text;}for(char&c:bytes)if(c==0)c='\n';return wide(bytes);}
inline std::vector<DiscoveredPluginFolder>discoverPluginFolders(const fs::path&roaming,const fs::path&local,const fs::path&documents,bool registry=true){std::vector<DiscoveredPluginFolder>out;std::set<std::wstring>seen;auto add=[&](std::wstring value,const std::wstring&source){value=trimPluginPath(value);wchar_t expanded[32768]{};DWORD n=ExpandEnvironmentStringsW(value.c_str(),expanded,32768);if(!n||n>=32768)return;fs::path p(expanded);std::error_code ec;if(!p.is_absolute()||p==p.root_path()||!fs::is_directory(p,ec))return;auto canonical=fs::weakly_canonical(p,ec);if(!ec)p=canonical;if(seen.insert(pluginPathKey(p)).second)out.push_back({p,source});};
    auto config=[&](const fs::path&path,const std::wstring&source){for(auto&value:pluginPathsFromConfig(readPluginConfig(path)))add(value,source);};
    config(roaming/L"REAPER/reaper.ini",L"Host settings");
    for(auto base:{roaming/L"Ableton",roaming/L"Steinberg",roaming/L"PreSonus",roaming/L"Bitwig Studio",local/L"Bitwig Studio",documents/L"Bitwig Studio"}){std::error_code ec;if(!fs::is_directory(base,ec))continue;size_t visited=0;for(fs::recursive_directory_iterator i(base,fs::directory_options::skip_permission_denied,ec),end;i!=end&&visited++<4096;i.increment(ec)){if(ec){ec.clear();continue;}if(i.depth()>3){i.disable_recursion_pending();continue;}if(i->is_directory(ec))continue;auto name=pluginPathKey(i->path().filename());if(name==L"preferences.cfg"||name==L"vstplugins.settings"||name==L"plugins.settings"||name==L"vstplugins.xml"||name.find(L"vst2xplugin searchpaths")==0||name==L"plugin-locations")config(i->path(),L"Host settings");}}
    if(registry){auto values=[&](HKEY root,const std::wstring&path,bool all){HKEY key=nullptr;if(RegOpenKeyExW(root,path.c_str(),0,KEY_READ|KEY_WOW64_64KEY,&key)!=ERROR_SUCCESS)return;for(DWORD i=0;i<256;i++){wchar_t name[512]{},data[32768]{};DWORD chars=512,bytes=sizeof(data)-2,type=0;LONG result=RegEnumValueW(key,i,name,&chars,nullptr,&type,(BYTE*)data,&bytes);if(result==ERROR_NO_MORE_ITEMS)break;if(result!=ERROR_SUCCESS||(type!=REG_SZ&&type!=REG_EXPAND_SZ))continue;data[std::min<size_t>(bytes/2,32767)]=0;auto lowered=pluginPathKey(name);if(all||lowered.find(L"vst")!=lowered.npos||lowered==L"path")add(data,L"Host settings");}RegCloseKey(key);};
        values(HKEY_LOCAL_MACHINE,L"SOFTWARE\\VST",true);values(HKEY_CURRENT_USER,L"SOFTWARE\\VST",true);
        // This is a preferences interoperability reader, not a dependency on a host.
        std::wstring list=L"Software\\Image-Line\\Shared\\Plugin search paths\\List";HKEY key=nullptr;if(RegOpenKeyExW(HKEY_CURRENT_USER,list.c_str(),0,KEY_READ,&key)==ERROR_SUCCESS){for(DWORD i=0;i<512;i++){wchar_t child[256]{};DWORD chars=256;if(RegEnumKeyExW(key,i,child,&chars,nullptr,nullptr,nullptr,nullptr)!=ERROR_SUCCESS)break;HKEY entry=nullptr;if(RegOpenKeyExW(key,child,0,KEY_READ,&entry)!=ERROR_SUCCESS)continue;DWORD selected=1,kind=0,bytes=4;RegQueryValueExW(entry,L"selected",nullptr,nullptr,(BYTE*)&selected,&bytes);bytes=4;RegQueryValueExW(entry,L"plugclass",nullptr,nullptr,(BYTE*)&kind,&bytes);wchar_t path[32768]{};bytes=sizeof(path)-2;DWORD type=0;if(selected&&kind!=2&&kind!=3&&RegQueryValueExW(entry,L"path",nullptr,&type,(BYTE*)path,&bytes)==ERROR_SUCCESS&&(type==REG_SZ||type==REG_EXPAND_SZ)){path[std::min<size_t>(bytes/2,32767)]=0;add(path,L"Host settings");}RegCloseKey(entry);}RegCloseKey(key);}}
    return out;
}
inline std::vector<DiscoveredPluginFolder>discoverPluginFolders(){try{return discoverPluginFolders(knownDirectory(FOLDERID_RoamingAppData),knownDirectory(FOLDERID_LocalAppData),knownDirectory(FOLDERID_Documents));}catch(...){return{};}}
}
